const keywords = $('03 Keyword Dataset').first().json.keywords || [];
const formData = $('01 Form Submission Webhook').first().json || {};
const runId = Date.now().toString(36);

const highPriorityKWs = keywords.filter(k => k.priority === 'High').slice(0, 10);

const prompts = highPriorityKWs.map((kw, idx) => {
  const tierCode = kw.offer_tier.replace('Tier ', 'T');
  const catCode = kw.prompt_category.replace(/\s+/g, '').replace('&', 'AND');
  const intentCode = kw.search_intent[0];
  const signalCode = kw.icp_signal.replace(' ', '');
  const marketCode = kw.market;
  const langCode = kw.language[0].toUpperCase();
  const typeCode = kw.content_type.replace(/\s+/g, '').replace('/', '');

  const promptId = `ZERENE_${tierCode}_${catCode}_${intentCode}_${signalCode}_${marketCode}_${langCode}_${typeCode}`;

  return {
    priority: 'High',
    prompt_id: promptId,
    prompt_category: kw.prompt_category,
    offer_tier: kw.offer_tier,
    audience: kw.audience,
    search_intent: kw.search_intent,
    icp_signal: kw.icp_signal,
    market: kw.market,
    language: kw.language,
    segment: kw.segment,
    content_type: kw.content_type,
    target_ai_prompt: kw.ai_prompt,
    primary_keyword: kw.keyword,
    secondary_keywords: kw.ai_prompt,
    business_objective: 'High-intent lead generation',
    expected_geo_outcome: 'Brand visibility, share of voice, qualified leads',
    linked_keyword_ids: kw.keyword_id,
    ready_to_use_prompt: kw.ai_prompt
  };
});

return prompts.map((p) => [{ json: p }]);
